import networkx as nx
from z3 import *

def solve():
    n = 19
    girth = 7
    min_edges = 37

    # We can just use a SAT solver to find if there's any graph with 19 vertices, girth >= 7, and >= 37 edges.
    # Actually, let's just check the maximum number of edges for n=19, girth=7.

    s = Solver()
    edges = [[Bool(f"e_{i}_{j}") for j in range(n)] for i in range(n)]

    for i in range(n):
        s.add(Not(edges[i][i]))
        for j in range(i+1, n):
            s.add(edges[i][j] == edges[j][i])

    # No cycles of length 3
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                s.add(Not(And(edges[i][j], edges[j][k], edges[k][i])))

    # No cycles of length 4
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    # permutations of 4 vertices
                    s.add(Not(And(edges[i][j], edges[j][k], edges[k][l], edges[l][i])))
                    s.add(Not(And(edges[i][j], edges[j][l], edges[l][k], edges[k][i])))
                    s.add(Not(And(edges[i][k], edges[k][j], edges[j][l], edges[l][i])))

    # This might be too slow to build for length 5 and 6.
    print("Constraints built for 3 and 4")
solve()
